@pytest.mark.parametrize('seed,selector,mode', [ (17, 'rarest', 'forward'), (17, 'rarest', 'inverse'), (17, 'rarest', 'twice'), (2**63 - 1, 'lowest', 'twice'), ]) def test_saved_color_shortcuts_are_refuted_by_visible_demonstrations(seed, selector, mode): def transfer(c, name): if mode == 'inverse': name = {'rotate_cw': 'rotate_ccw', 'rotate_ccw': 'rotate_cw'}.get(name, name) first = transform(c, name) return transform(first, name) if mode == 'twice' else first refutations = [] for grid in sampler().sample_inputs(seed)[0]: (a, b, c), correct = inspect(grid) cells = [v for row in a for v in row if v] counts = {v: cells.count(v) for v in set(cells)} color = min(counts, key=lambda v: (counts[v], v)) if selector == 'rarest' else min(counts) ma = [[int(v == color) for v in row] for row in a] mb = [[int(v == color) for v in row] for row in b] wrong = candidates(ma, mb)[0] refutations.append(transfer(c, correct) != transfer(c, wrong)) > assert any(refutations), 'saved color-subset shortcut still fits every visible demonstration' E AssertionError: saved color-subset shortcut still fits every visible demonstration E assert False E + where False = any([False, False, False])
